 * Author: @omer-fils-elenga (https://tailwindflex.com/@omer-fils-elenga)
 * Source: https://tailwindflex.com/@omer-fils-elenga/plasma-2
 * Attribution: Créé par @omer-fils-elenga sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function Plasma2() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Plasma Effect Control</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }
        body {
            width: 100vw;
            height: 100vh;
            overflow: hidden;
            background: #000;
            font-family: 'Segoe UI', system-ui, sans-serif;
        }
        #container {
            width: 100%;
            height: 100%;
            position: relative;
            overflow: hidden;
        }
        canvas {
            width: 100%;
            height: 100%;
            display: block;
        }

        /* Menu Styles */
        #controlMenu {
            position: fixed;
            top: 20px;
            right: 20px;
            background: rgba(15, 15, 25, 0.85);
            backdrop-filter: blur(10px);
            border-radius: 12px;
            padding: 20px;
            width: 320px;
            color: #fff;
            z-index: 1000;
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
            border: 1px solid rgba(255, 255, 255, 0.1);
            transition: all 0.3s ease;
        }

        #controlMenu.collapsed {
            width: 60px;
            height: 60px;
            padding: 0;
            overflow: hidden;
        }

        #controlMenu.collapsed .menu-content {
            display: none;
        }

        #controlMenu.collapsed .menu-toggle {
            transform: rotate(180deg);
        }

        .menu-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 20px;
            padding-bottom: 15px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        }

        .menu-header h2 {
            font-size: 18px;
            font-weight: 600;
            color: #fff;
            letter-spacing: 0.5px;
        }

        .menu-toggle {
            width: 32px;
            height: 32px;
            background: rgba(255, 255, 255, 0.1);
            border: none;
            border-radius: 8px;
            color: #fff;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s ease;
        }

        .menu-toggle:hover {
            background: rgba(255, 255, 255, 0.2);
            transform: scale(1.1);
        }

        .menu-toggle i {
            font-size: 18px;
        }

        .control-group {
            margin-bottom: 20px;
            position: relative;
        }

        .control-label {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 8px;
            font-size: 14px;
            color: rgba(255, 255, 255, 0.8);
        }

        .control-value {
            font-weight: 600;
            color: #00ffff;
            font-family: 'Consolas', monospace;
            background: rgba(0, 255, 255, 0.1);
            padding: 2px 8px;
            border-radius: 4px;
        }

        /* Slider Styles */
        .slider-container {
            position: relative;
            height: 40px;
        }

        .slider {
            -webkit-appearance: none;
            width: 100%;
            height: 6px;
            background: rgba(255, 255, 255, 0.1);
            border-radius: 3px;
            outline: none;
            position: absolute;
            top: 50%;
            transform: translateY(-50%);
        }

        .slider::-webkit-slider-thumb {
            -webkit-appearance: none;
            width: 20px;
            height: 20px;
            border-radius: 50%;
            background: #00ffff;
            cursor: pointer;
            box-shadow: 0 0 10px rgba(0, 255, 255, 0.5);
            border: 2px solid rgba(255, 255, 255, 0.8);
            transition: all 0.2s ease;
        }

        .slider::-webkit-slider-thumb:hover {
            background: #00ffff;
            box-shadow: 0 0 15px rgba(0, 255, 255, 0.8);
            transform: scale(1.2);
        }

        .slider::-moz-range-thumb {
            width: 20px;
            height: 20px;
            border-radius: 50%;
            background: #00ffff;
            cursor: pointer;
            box-shadow: 0 0 10px rgba(0, 255, 255, 0.5);
            border: 2px solid rgba(255, 255, 255, 0.8);
        }

        /* Color Picker */
        .color-picker-container {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        #colorPicker {
            width: 40px;
            height: 40px;
            border: none;
            border-radius: 8px;
            cursor: pointer;
            background: transparent;
        }

        .color-preview {
            width: 100%;
            height: 40px;
            border-radius: 8px;
            background: linear-gradient(90deg, 
                rgba(5, 76, 245, 1) 0%, 
                rgba(0, 255, 255, 1) 50%, 
                rgba(255, 0, 255, 1) 100%);
            border: 2px solid rgba(255, 255, 255, 0.2);
        }

        /* Direction Select */
        .direction-select {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 8px;
            margin-top: 8px;
        }

        .direction-btn {
            padding: 10px;
            background: rgba(255, 255, 255, 0.05);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 8px;
            color: rgba(255, 255, 255, 0.7);
            cursor: pointer;
            text-align: center;
            font-size: 12px;
            font-weight: 500;
            transition: all 0.2s ease;
        }

        .direction-btn:hover {
            background: rgba(255, 255, 255, 0.1);
            color: #fff;
        }

        .direction-btn.active {
            background: rgba(0, 255, 255, 0.2);
            color: #00ffff;
            border-color: rgba(0, 255, 255, 0.5);
            box-shadow: 0 0 15px rgba(0, 255, 255, 0.2);
        }

        /* Toggle Switch */
        .toggle-container {
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .toggle-switch {
            position: relative;
            width: 50px;
            height: 26px;
        }

        .toggle-switch input {
            opacity: 0;
            width: 0;
            height: 0;
        }

        .toggle-slider {
            position: absolute;
            cursor: pointer;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: rgba(255, 255, 255, 0.1);
            border-radius: 34px;
            transition: .4s;
        }

        .toggle-slider:before {
            position: absolute;
            content: "";
            height: 18px;
            width: 18px;
            left: 4px;
            bottom: 4px;
            background-color: #fff;
            border-radius: 50%;
            transition: .4s;
        }

        input:checked + .toggle-slider {
            background-color: rgba(0, 255, 255, 0.5);
        }

        input:checked + .toggle-slider:before {
            transform: translateX(24px);
            background-color: #00ffff;
            box-shadow: 0 0 10px rgba(0, 255, 255, 0.8);
        }

        /* Presets */
        .presets-container {
            margin-top: 25px;
            padding-top: 20px;
            border-top: 1px solid rgba(255, 255, 255, 0.1);
        }

        .presets-title {
            font-size: 14px;
            color: rgba(255, 255, 255, 0.8);
            margin-bottom: 12px;
        }

        .preset-buttons {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 8px;
        }

        .preset-btn {
            padding: 8px;
            background: rgba(255, 255, 255, 0.05);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 6px;
            color: rgba(255, 255, 255, 0.7);
            cursor: pointer;
            font-size: 11px;
            transition: all 0.2s ease;
            text-align: center;
        }

        .preset-btn:hover {
            background: rgba(255, 255, 255, 0.1);
            transform: translateY(-2px);
        }

        /* Status Bar */
        #statusBar {
            position: fixed;
            bottom: 20px;
            left: 50%;
            transform: translateX(-50%);
            background: rgba(15, 15, 25, 0.8);
            backdrop-filter: blur(10px);
            border-radius: 8px;
            padding: 10px 20px;
            color: #fff;
            font-size: 14px;
            display: flex;
            align-items: center;
            gap: 15px;
            z-index: 1000;
            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
            border: 1px solid rgba(255, 255, 255, 0.1);
        }

        .status-item {
            display: flex;
            align-items: center;
            gap: 6px;
            color: rgba(255, 255, 255, 0.8);
        }

        .status-value {
            color: #00ffff;
            font-weight: 600;
        }

        /* Help Text */
        #helpText {
            position: fixed;
            bottom: 70px;
            left: 20px;
            color: rgba(255, 255, 255, 0.5);
            font-size: 12px;
            max-width: 200px;
            line-height: 1.4;
        }

        /* Animation for menu toggle */
        @keyframes slideIn {
            from {
                opacity: 0;
                transform: translateY(-10px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        .menu-content {
            animation: slideIn 0.3s ease;
        }

        /* Mobile responsive */
        @media (max-width: 768px) {
            #controlMenu {
                width: 300px;
                right: 10px;
                top: 10px;
            }

            #controlMenu.collapsed {
                width: 50px;
                height: 50px;
            }

            #statusBar {
                bottom: 10px;
                left: 10px;
                right: 10px;
                transform: none;
                justify-content: space-around;
                padding: 8px 15px;
            }
        }
    </style>

    <!-- Font Awesome for icons -->
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
</head>
<body>

<div id="container"></div>

<!-- Control Menu -->
<div id="controlMenu">
    <div class="menu-header">
        <h2>Plasma Controls</h2>
        <button class="menu-toggle" id="menuToggle">
            <i class="fas fa-chevron-right"></i>
        </button>
    </div>

    <div class="menu-content">
        <!-- Color Control -->
        <div class="control-group">
            <div class="control-label">
                <span>Color</span>
                <span id="colorValue" class="control-value">#054CF5</span>
            </div>
            <div class="color-picker-container">
                <input type="color" id="colorPicker" value="#054CF5">
                <div class="color-preview" id="colorPreview"></div>
            </div>
        </div>

        <!-- Speed Control -->
        <div class="control-group">
            <div class="control-label">
                <span>Speed</span>
                <span id="speedValue" class="control-value">1.0x</span>
            </div>
            <div class="slider-container">
                <input type="range" min="0.1" max="3" step="0.1" value="1" class="slider" id="speedSlider">
            </div>
        </div>

        <!-- Direction Control -->
        <div class="control-group">
            <div class="control-label">
                <span>Direction</span>
                <span id="directionValue" class="control-value">Forward</span>
            </div>
            <div class="direction-select">
                <button class="direction-btn active" data-direction="forward">Forward</button>
                <button class="direction-btn" data-direction="reverse">Reverse</button>
                <button class="direction-btn" data-direction="pingpong">Ping Pong</button>
            </div>
        </div>

        <!-- Scale Control -->
        <div class="control-group">
            <div class="control-label">
                <span>Scale</span>
                <span id="scaleValue" class="control-value">1.0</span>
            </div>
            <div class="slider-container">
                <input type="range" min="0.5" max="3" step="0.1" value="1" class="slider" id="scaleSlider">
            </div>
        </div>

        <!-- Opacity Control -->
        <div class="control-group">
            <div class="control-label">
                <span>Opacity</span>
                <span id="opacityValue" class="control-value">100%</span>
            </div>
            <div class="slider-container">
                <input type="range" min="0" max="100" step="1" value="100" class="slider" id="opacitySlider">
            </div>
        </div>

        <!-- Mouse Interaction Toggle -->
        <div class="control-group">
            <div class="control-label toggle-container">
                <span>Mouse Interaction</span>
                <label class="toggle-switch">
                    <input type="checkbox" id="mouseToggle" checked>
                    <span class="toggle-slider"></span>
                </label>
            </div>
        </div>

        <!-- Presets -->
        <div class="presets-container">
            <div class="presets-title">Presets</div>
            <div class="preset-buttons">
                <button class="preset-btn" data-preset="ocean">Ocean</button>
                <button class="preset-btn" data-preset="fire">Fire</button>
                <button class="preset-btn" data-preset="neon">Neon</button>
                <button class="preset-btn" data-preset="aurora">Aurora</button>
            </div>
        </div>
    </div>
</div>

<!-- Status Bar -->
<div id="statusBar">
    <div class="status-item">
        <i class="fas fa-tachometer-alt"></i>
        <span>Speed: <span id="statusSpeed" class="status-value">1.0x</span></span>
    </div>
    <div class="status-item">
        <i class="fas fa-compress-arrows-alt"></i>
        <span>Scale: <span id="statusScale" class="status-value">1.0</span></span>
    </div>
    <div class="status-item">
        <i class="fas fa-eye"></i>
        <span>Opacity: <span id="statusOpacity" class="status-value">100%</span></span>
    </div>
    <div class="status-item">
        <i class="fas fa-mouse-pointer"></i>
        <span>Mouse: <span id="statusMouse" class="status-value">ON</span></span>
    </div>
</div>

<!-- Help Text -->
<div id="helpText">
    Press <kbd>M</kbd> to toggle menu | <kbd>R</kbd> to reset | <kbd>H</kbd> to hide
</div>



</body>
</html>" }} />
  );
}
